🏗 Practice 3: Project Gutenberg
The core tokenise-count-plot loop runs right here in your browser on Jane Austen’s novels; the Gutenberg downloads wait for your own R session.






NoteBasic





Find the ten most common meaningful words in Pride & Prejudice. Two blanks: the function that turns lines of text into one-word-per-row, and the stopword table to anti_join() away.















NoteHint





The tokenizer is the very first tidytext function this session taught, and tidytext ships a built-in data frame of English stopwords called stop_words.











TipSolution





library(dplyr)
library(tidytext)
library(janeaustenr)
library(ggplot2)

austen_books() |&gt;
  filter(book == "Pride & Prejudice") |&gt;
  unnest_tokens(word, text) |&gt;
  anti_join(stop_words, by = "word") |&gt;
  count(word, sort = TRUE) |&gt;
  slice_head(n = 10) |&gt;
  ggplot(aes(x = n, y = reorder(word, n))) +
  geom_col() +
  labs(y = NULL)













ImportantIntermediate





Words rarely travel alone. Tokenise Emma into bigrams (pairs of consecutive words), split each pair, drop the pairs where either half is a stopword, and count what remains. Two blanks in the tokenizer call.















NoteHint





unnest_tokens() speaks more than words: its token = argument accepts "ngrams", and n = says how many words per gram.











TipSolution





library(dplyr)
library(tidyr)
library(tidytext)
library(janeaustenr)

austen_books() |&gt;
  filter(book == "Emma") |&gt;
  unnest_tokens(bigram, text, token = "ngrams", n = 2) |&gt;
  separate(bigram, into = c("word1", "word2"), sep = " ") |&gt;
  filter(!word1 %in% stop_words$word,
         !word2 %in% stop_words$word) |&gt;
  count(word1, word2, sort = TRUE) |&gt;
  slice_head(n = 10)













CautionAdvanced





These need live downloads and your own R session:

Install the gutenbergr package install.packages("gutenbergr"), pick a book from the library and download it to R, then carry out whichever sentiment analysis you prefer and plot it.
Carry out sentiment analysis for a book of your choice using all sentiment lexicons available in the get_sentiments() function: AFINN, NRC, Bing and loughran. Describe each result and the differences between them.
Write a function that downloads and cleans the text of any book in Project Gutenberg, and another that does sentiment analysis of any book in Project Gutenberg.







TipSolution sketch







Code
library(gutenbergr)
library(tidytext)
library(tidyverse)

# Download the descent of man - Charles Darwin ####
gutenbergr::gutenberg_download(gutenberg_id = 34967, mirror = "http://mirrors.xmission.com/gutenberg/") |&gt;
  tidytext::unnest_tokens(word, text) |&gt;
  dplyr::anti_join(stopwords::stopwords(language = "en") |&gt;
                     as_tibble() |&gt;
                     dplyr::rename(word=1),
                   by="word") |&gt;
  dplyr::left_join(get_sentiments("afinn"), by="word") |&gt;
  dplyr::group_by(value) |&gt;
  dplyr::mutate(n = n(),
                p = n/sum(n),
                c = case_when(value&lt;0 ~ "Negative",
                              value==0 ~ "Neutral",
                              value&gt;0 ~ "Positive") |&gt;
                  factor()) |&gt;
  ggplot(aes(x=value,y=n,color=c))+
  geom_col(show.legend = FALSE)+
  geom_vline(xintercept = 0)+
  scale_x_continuous(breaks=seq(from=-5,to=5,by=1))+
  scale_color_brewer(palette = "Set1")+
  annotate("text",x=-4,y=1000000, label ="Negative", color = "red")+
  annotate("text",x=4,y=1000000, label ="Positive", color = "blue")+
  labs(title = "The Descent of Man (Charles Darwin, 1871)",
       subtitle = "Sentiment analysis",
    x="AFINN lexicon",
    y= "Word frequency",
    caption = "Source: R4DEV workshop")

# Through a function ####
book_sentiments &lt;- function(author_name,book_name) {

  # Extract ID 
  gutenbergr::gutenberg_works() |&gt; 
    dplyr::filter(str_detect(author,author_name), str_detect(title,book_name)) |&gt; 
    dplyr::select(gutenberg_id) |&gt; 
    as.numeric() |&gt;
    # Download book
    gutenbergr::gutenberg_download(mirror = "http://mirrors.xmission.com/gutenberg/") |&gt;
    # unnest tokens
    tidytext::unnest_tokens(word, text) |&gt;
    # Exclude stopwords
    dplyr::anti_join(stopwords::stopwords(language = "en") |&gt;
                     as_tibble() |&gt;
                     dplyr::rename(word=1),
                   by="word") |&gt;
    # Join sentiments
    dplyr::left_join(get_sentiments("afinn"), by="word") |&gt;
    dplyr::group_by(value) |&gt;
    dplyr::mutate(n = n(),
                p = n/sum(n),
                c = case_when(value&lt;0 ~ "Negative",
                              value==0 ~ "Neutral",
                              value&gt;0 ~ "Positive") |&gt;
                  factor()) |&gt;
    # Plot results
    ggplot(aes(x=value,y=n,color=c))+
    geom_col(show.legend = FALSE)+
    geom_vline(xintercept = 0)+
    scale_x_continuous(breaks=seq(from=-5,to=5,by=1))+
    scale_color_brewer(palette = "Set1")+
    annotate("text",x=-4,y=1000000, label ="Negative", color = "red")+
    annotate("text",x=4,y=1000000, label ="Positive", color = "blue")+
    labs(title = paste0("Sentiment analysis for ",print(book_name)," by ",print(author_name)), 
           subtitle = "Book from Project Gutenberg",
    x="Sentimen AFINN",
    y= "Word frequency",
    caption = "Source: R4DEV workshop")

}

# Plot a book based on the author name and title ####
book_sentiments("Hume, David","A Treatise of Human Nature")

PART II: The permutation test, by hand
Our statistic is the difference in mean bill length:


Show the code
observed_diff &lt;- penguins |&gt;
  dplyr::summarise(m = mean(bill_length_mm), .by = species) |&gt;
  dplyr::summarise(diff = m[species == "Chinstrap"] - m[species == "Adelie"]) |&gt;
  dplyr::pull(diff)

observed_diff


[1] 10.04243


Now the null world. If species had nothing to do with bill length, the species labels would be arbitrary stickers –so we can build that world by shuffling the stickers and leaving the bills alone:


Show the code
set.seed(2024)

null_world &lt;- tibble(replicate = 1:5000) |&gt;
  dplyr::mutate(
    diff = purrr::map_dbl(replicate, \(i) {
      penguins |&gt;
1        dplyr::mutate(species = sample(species)) |&gt;
        dplyr::summarise(m = mean(bill_length_mm), .by = species) |&gt;
        dplyr::summarise(d = m[species == "Chinstrap"] - m[species == "Adelie"]) |&gt;
        dplyr::pull(d)
      })
    )

null_world |&gt;
  ggplot(aes(diff)) +
  geom_histogram(bins = 60, fill = "#226F7F") +
  geom_vline(xintercept = observed_diff, color = "#F75431", linewidth = 1) +
  labs(
    x = "Difference in means when species labels are shuffled",
    y = NULL,
    title = "5,000 worlds where species doesn't matter",
    subtitle = "The orange line is what we actually observed. It is not even close."
    ) +
  theme_minimal()



1

sample(species) with no other arguments shuffles the column –every penguin keeps its bill, gets a random label. This single line is the null hypothesis, written in R instead of Greek.











The verdict needs no formula: in 5,000 label-shuffled worlds, the biggest difference noise ever produced is a fraction of what we observed. The p-value is the share of null worlds at least as extreme as reality:


Show the code
mean(abs(null_world$diff) &gt;= abs(observed_diff))


[1] 0


Zero out of 5,0002. A t-test would have told you the same thing through a formula –now you know what the formula is estimating.

PART V: The gallery –break the assumption, watch the estimate 🎛️
Reading about natural experiments is one thing; feeling where they break is another. Each machine below wires up a world where the true effect is known, because we built it –and then estimates that effect the way a real study would. Next to every plot sits the design’s DAG, and next to the DAG, sliders.
Here is the trick, and it is Hernán’s motto run in reverse: every design in this gallery works because of an arrow that isn’t there. Parallel trends is a missing arrow. Exclusion is a missing arrow. The red slider on each machine draws the forbidden arrow into existence –you will see it appear on the DAG– and the readout tiles show the estimate drifting away from the truth as you do5.



Show the code
C = ({treat: "#F75431", ctrl: "#0E8CA8", ghost: "#8A979C", danger: "#D7263D"})









Show the code
fmt = d3.format(".2f")









Show the code
olsFit = (pts) =&gt; {
  const mx = d3.mean(pts, d =&gt; d.x), my = d3.mean(pts, d =&gt; d.y);
  const b = d3.sum(pts, d =&gt; (d.x - mx) * (d.y - my)) / d3.sum(pts, d =&gt; (d.x - mx) ** 2);
  return {a: my - b * mx, b};
}









Show the code
tiles = (items) =&gt; htl.html`&lt;div class="ci-tiles"&gt;${items.map(d =&gt; htl.html`&lt;div class="ci-tile" style="border-top-color:${d.color ?? "var(--bs-border-color)"}"&gt;&lt;div class="lab"&gt;${d.lab}&lt;/div&gt;&lt;div class="val"&gt;${d.val}&lt;/div&gt;&lt;/div&gt;`)}&lt;/div&gt;`









Show the code
drawDAG = ({id, w = 340, h = 170, nodes, edges}) =&gt; {
  const R = 17;
  const N = new Map(nodes.map(d =&gt; [d.id, d]));
  const parts = edges
    .filter(e =&gt; (e.opacity ?? 1) &gt; 0.03)
    .map((e, i) =&gt; {
      const s = N.get(e.from), t = N.get(e.to);
      const rs = s.hidden ? 2 : R + 3, rt = t.hidden ? 2 : R + 8;
      const dx = t.x - s.x, dy = t.y - s.y, L = Math.hypot(dx, dy);
      const ux = dx / L, uy = dy / L;
      const x1 = s.x + ux * rs, y1 = s.y + uy * rs;
      const x2 = t.x - ux * rt, y2 = t.y - uy * rt;
      const bend = e.bend ?? 0;
      const cx = (x1 + x2) / 2 - uy * bend, cy = (y1 + y2) / 2 + ux * bend;
      const mid = {x: (x1 + 2 * cx + x2) / 4, y: (y1 + 2 * cy + y2) / 4};
      const col = e.color ?? "currentColor";
      return htl.svg`&lt;g opacity=${e.opacity ?? 1}&gt;
        &lt;marker id="${id}-arr${i}" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6.5" markerHeight="6.5" orient="auto-start-reverse"&gt;&lt;path d="M0,0L10,5L0,10z" fill=${col}&gt;&lt;/path&gt;&lt;/marker&gt;
        &lt;path d="M${x1},${y1} Q${cx},${cy} ${x2},${y2}" fill="none" stroke=${col} stroke-width=${e.width ?? 1.8} stroke-dasharray=${e.dashed ? "5 4" : null} marker-end="url(#${id}-arr${i})"&gt;&lt;/path&gt;
        ${e.label ? htl.svg`&lt;text x=${mid.x + (e.lx ?? 0)} y=${mid.y + (e.ly ?? -7)} fill=${col} font-size="10.5" font-weight="600" text-anchor="middle"&gt;${e.label}&lt;/text&gt;` : null}
      &lt;/g&gt;`;
    });
  const dots = nodes.filter(n =&gt; !n.hidden).map(n =&gt; htl.svg`&lt;g&gt;
      &lt;circle cx=${n.x} cy=${n.y} r=${R} fill="var(--bs-body-bg, white)" stroke=${n.dashed ? "var(--bs-secondary-color, #888)" : "currentColor"} stroke-width="1.6" stroke-dasharray=${n.dashed ? "4 3" : null}&gt;&lt;/circle&gt;
      &lt;text x=${n.x} y=${n.y + 4.5} text-anchor="middle" font-size="13" font-weight="700" fill=${n.dashed ? "var(--bs-secondary-color, #888)" : "currentColor"}&gt;${n.id}&lt;/text&gt;
      ${n.label ? htl.svg`&lt;text x=${n.x} y=${n.y + (n.ldy ?? R + 13)} text-anchor="middle" font-size="10" fill="var(--bs-secondary-color, #888)"&gt;${n.label}&lt;/text&gt;` : null}
    &lt;/g&gt;`);
  return htl.svg`&lt;svg viewBox="0 0 ${w} ${h}" style="max-width:${w}px;width:100%;height:auto;overflow:visible"&gt;${parts}${dots}&lt;/svg&gt;`;
}








📈 DiD✂️ RDD🎲 IV🎯 Matching🏢 Fixed effects🎼 Synthetic control


A job-training program arrives in one region at \(t = 6\) and never reaches its neighbor. Comparing the regions after the program is confounded (they differ for a hundred reasons); comparing the treated region before vs after is confounded too (things trend over time anyway). DiD’s move: compare the changes –how much the treated region moved, minus how much the control moved.
That subtraction is only an effect under one assumption: absent treatment, both regions would have moved in parallel. Level differences are fine –the arrow \(G \to Y\) can exist. What must not exist is an arrow from group to trend. Drag the red slider and draw it.




Show the code
drawDAG({
  id: "dag-did",
  nodes: [
    {id: "G", x: 55, y: 45, label: "group"},
    {id: "T", x: 55, y: 125, label: "time"},
    {id: "D", x: 170, y: 85, label: "treatment"},
    {id: "Y", x: 285, y: 85, label: "outcome"},
    {id: "v", x: 169, y: 127, hidden: true}
  ],
  edges: [
    {from: "G", to: "D"},
    {from: "T", to: "D"},
    {from: "D", to: "Y", width: 2.4},
    {from: "G", to: "Y", bend: -46},
    {from: "T", to: "Y", bend: 46},
    {from: "G", to: "v", color: C.danger, dashed: true,
     width: 1.6 + 2 * Math.abs(did_drift),
     opacity: Math.min(1, Math.abs(did_drift) / 0.1),
     label: "G bends the trend!", lx: -6, ly: 18}
  ]
})











Show the code
viewof did_effect = Inputs.range([0, 6], {value: 3, step: 0.25, label: "True treatment effect"})









Show the code
viewof did_drift = Inputs.range([-0.6, 0.6], {value: 0, step: 0.05, label: "🚨 Differential trend (the violation)"})









Show the code
tiles([
  {lab: "truth (wired in)", val: fmt(did_effect), color: "currentColor"},
  {lab: "DiD estimate", val: fmt(didEst), color: C.ctrl},
  {lab: "bias", val: d3.format("+.2f")(didEst - did_effect),
   color: Math.abs(didEst - did_effect) &gt; 0.3 ? C.danger : C.ghost}
])











Show the code
did = {
  const noise = d3.randomNormal.source(d3.randomLcg(0.4242))(0, 0.9);
  const rows = [];
  for (const g of ["Control", "Treated"]) {
    for (let t = 1; t &lt;= 10; t++) {
      for (let i = 0; i &lt; 30; i++) {
        const y = (g === "Treated" ? 4 : 1) + 0.5 * t
          + (g === "Treated" ? did_drift * (t - 1) : 0)
          + (g === "Treated" && t &gt;= 6 ? did_effect : 0)
          + noise();
        rows.push({g, t, y});
      }
    }
  }
  return rows;
}









Show the code
didMeans = {
  const rows = [];
  for (const [g, ts] of d3.rollups(did, v =&gt; d3.mean(v, d =&gt; d.y), d =&gt; d.g, d =&gt; d.t)) {
    for (const [t, m] of ts) rows.push({g, t, m});
  }
  return rows.sort((a, b) =&gt; a.t - b.t);
}









Show the code
didCF = {
  const M = (g, t) =&gt; didMeans.find(d =&gt; d.g === g && d.t === t).m;
  return d3.range(5, 11).map(t =&gt; ({t, m: M("Treated", 5) + M("Control", t) - M("Control", 5)}));
}









Show the code
didEst = {
  const pre = d3.range(1, 6), post = d3.range(6, 11);
  const M = (g, ts) =&gt; d3.mean(didMeans.filter(d =&gt; d.g === g && ts.includes(d.t)), d =&gt; d.m);
  return (M("Treated", post) - M("Treated", pre)) - (M("Control", post) - M("Control", pre));
}









Show the code
Plot.plot({
  width: Math.min(width, 780),
  height: 420,
  marginLeft: 84,
  y: {domain: [-1, 22], label: "Outcome", grid: true},
  x: {domain: [1, 11.6], label: "Time period", ticks: d3.range(1, 11)},
  color: {legend: true, domain: ["Control", "Treated"], range: [C.ctrl, C.treat]},
  marks: [
    Plot.ruleX([5.5], {stroke: "currentColor", strokeDasharray: "3 3", opacity: 0.5}),
    Plot.text([{x: 5.5, y: 21.4}], {x: "x", y: "y", text: ["treatment begins →"], dx: 6, textAnchor: "start", fill: "currentColor", opacity: 0.6, fontSize: 11}),
    Plot.dot(did, {x: "t", y: "y", fill: "g", opacity: 0.13, r: 2, title: d =&gt; `${d.g}, t = ${d.t}: ${fmt(d.y)}`}),
    Plot.line(didMeans, {x: "t", y: "m", stroke: "g", strokeWidth: 2.5}),
    Plot.line(didCF, {x: "t", y: "m", stroke: C.ghost, strokeWidth: 2, strokeDasharray: "6 4"}),
    Plot.text(didMeans.filter(d =&gt; d.t === 1), {x: "t", y: "m", text: "g", dx: -10, textAnchor: "end", fill: "g", fontWeight: 600, fontSize: 11.5}),
    Plot.text([didCF.at(-1)], {x: "t", y: "m", text: ["counterfactual"], dy: 16, dx: 4, textAnchor: "middle", fill: C.ghost, fontSize: 11}),
    Math.abs(didMeans.find(d =&gt; d.g === "Treated" && d.t === 10).m - didCF.at(-1).m) &gt; 0.25
      ? Plot.arrow([{}], {x1: 10.5, y1: didCF.at(-1).m, x2: 10.5, y2: didMeans.find(d =&gt; d.g === "Treated" && d.t === 10).m, stroke: "currentColor", strokeWidth: 1.6})
      : null,
    Plot.text([{x: 10.62, y: (didCF.at(-1).m + didMeans.find(d =&gt; d.g === "Treated" && d.t === 10).m) / 2}], {x: "x", y: "y", text: [`DiD = ${fmt(didEst)}`], textAnchor: "start", fontWeight: 700, fontSize: 11.5, fill: "currentColor"})
  ]
})







Try this. With the violation at 0, drag the true effect around: the estimate tracks the truth, because the dashed counterfactual –“treated, had nothing happened”– is exactly right. Now set the differential trend to \(+0.4\): the treated region was rising faster anyway, the counterfactual is drawn too flat, and DiD hands the extra trend to the program. Then look left of the dashed line: the pre-treatment lines are visibly not parallel. That is why every serious DiD paper opens with a plot of pre-trends –it is the one part of the assumption the data lets you audit.


A scholarship goes to everyone scoring at or above a cutoff, and to no one below. Students at 59.9 and 60.1 are, for all practical purposes, the same person on two sides of a bureaucratic line –so any jump in later outcomes exactly at the cutoff is the scholarship’s doing. The DAG shows why this works: the running variable \(X\) may affect the outcome however it likes, as long as its effect is smooth at the cutoff; only \(D\) is allowed to jump there.
The threat here is not a hidden arrow but a bad model of the smooth part. You estimate the jump by fitting a line on each side within a bandwidth around the cutoff. If the world is curved and your window is wide, straight lines mis-fit the curvature and the mistake lands in the jump.




Show the code
drawDAG({
  id: "dag-rdd",
  w: 340, h: 155,
  nodes: [
    {id: "X", x: 60, y: 75, label: "running var."},
    {id: "D", x: 170, y: 35, label: "scholarship"},
    {id: "Y", x: 285, y: 75, label: "outcome"}
  ],
  edges: [
    {from: "X", to: "D", label: "x ≥ cutoff", ly: -9},
    {from: "D", to: "Y", width: 2.4},
    {from: "X", to: "Y", bend: 42,
     color: Math.abs(rddFit.est - rdd_effect) &gt; 0.35 ? C.danger : "currentColor",
     label: Math.abs(rddFit.est - rdd_effect) &gt; 0.35 ? "your lines can't hold this curve!" : "must be smooth at the cutoff",
     ly: 16}
  ]
})











Show the code
viewof rdd_effect = Inputs.range([0, 4], {value: 2, step: 0.25, label: "True jump at the cutoff"})









Show the code
viewof rdd_bw = Inputs.range([1.5, 10], {value: 5, step: 0.5, label: "Bandwidth (window you fit in)"})









Show the code
viewof rdd_curve = Inputs.range([-1, 1], {value: 0, step: 0.1, label: "🚨 Curvature of the world (the danger)"})









Show the code
tiles([
  {lab: "truth (wired in)", val: fmt(rdd_effect), color: "currentColor"},
  {lab: "RDD estimate", val: fmt(rddFit.est), color: C.ctrl},
  {lab: "bias", val: d3.format("+.2f")(rddFit.est - rdd_effect),
   color: Math.abs(rddFit.est - rdd_effect) &gt; 0.35 ? C.danger : C.ghost},
  {lab: "points in window", val: `${rddFit.n} / 280`, color: C.ghost}
])











Show the code
rddPts = {
  const ux = d3.randomUniform.source(d3.randomLcg(0.111))(-10, 10);
  const ne = d3.randomNormal.source(d3.randomLcg(0.222))(0, 1.1);
  return d3.range(280).map(() =&gt; ({x: ux(), e: ne()}));
}









Show the code
rdd = rddPts.map(d =&gt; ({
  x: d.x,
  y: 3 + 0.3 * d.x + rdd_curve * 0.045 * d.x * d.x + (d.x &gt;= 0 ? rdd_effect : 0) + d.e,
  side: d.x &gt;= 0 ? "Above cutoff" : "Below cutoff",
  used: Math.abs(d.x) &lt;= rdd_bw
}))









Show the code
rddFit = {
  const L = olsFit(rdd.filter(d =&gt; d.side === "Below cutoff" && d.used));
  const R = olsFit(rdd.filter(d =&gt; d.side === "Above cutoff" && d.used));
  return {L, R, est: R.a - L.a, n: rdd.filter(d =&gt; d.used).length};
}









Show the code
Plot.plot({
  width: Math.min(width, 780),
  height: 420,
  x: {domain: [-10.5, 10.5], label: "Running variable (distance to cutoff)"},
  y: {domain: [-8, 17], label: "Outcome", grid: true},
  color: {legend: true, domain: ["Below cutoff", "Above cutoff"], range: [C.ctrl, C.treat]},
  marks: [
    Plot.rect([{}], {x1: -rdd_bw, x2: rdd_bw, y1: -8, y2: 17, fill: "currentColor", fillOpacity: 0.05}),
    Plot.ruleX([0], {stroke: "currentColor", strokeDasharray: "3 3", opacity: 0.55}),
    Plot.dot(rdd.filter(d =&gt; !d.used), {x: "x", y: "y", fill: C.ghost, opacity: 0.18, r: 2.6, title: d =&gt; `x = ${fmt(d.x)}, y = ${fmt(d.y)} (outside bandwidth)`}),
    Plot.dot(rdd.filter(d =&gt; d.used), {x: "x", y: "y", fill: "side", opacity: 0.55, r: 2.6, title: d =&gt; `x = ${fmt(d.x)}, y = ${fmt(d.y)}`}),
    Plot.line([{x: -rdd_bw, y: rddFit.L.a - rddFit.L.b * rdd_bw}, {x: 0, y: rddFit.L.a}], {x: "x", y: "y", stroke: C.ctrl, strokeWidth: 2.6}),
    Plot.line([{x: 0, y: rddFit.R.a}, {x: rdd_bw, y: rddFit.R.a + rddFit.R.b * rdd_bw}], {x: "x", y: "y", stroke: C.treat, strokeWidth: 2.6}),
    Math.abs(rddFit.est) &gt; 0.15
      ? Plot.arrow([{}], {x1: 0, y1: rddFit.L.a, x2: 0, y2: rddFit.R.a, stroke: "currentColor", strokeWidth: 1.6})
      : null,
    Plot.text([{x: 0.35, y: (rddFit.L.a + rddFit.R.a) / 2}], {x: "x", y: "y", text: [`jump = ${fmt(rddFit.est)}`], textAnchor: "start", fontWeight: 700, fontSize: 11.5, fill: "currentColor"})
  ]
})







