scSeries = {
  const s = t =&gt; 2.2 * Math.sin(t / 2.3);
  const donors = scBase.donors.map((d, j) =&gt; ({
    j,
    vals: d3.range(1, 17).map(t =&gt; d.a + d.b * t + d.c * s(t) + 0.12 * d.noise[t - 1])
  }));
  const treated = d3.range(1, 17).map(t =&gt; {
    const hull = d3.sum(donors.map((d, j) =&gt; scBase.wStar[j] * d.vals[t - 1]));
    const quirk = sc_unique * (0.45 * (t - 1) + 2.4 * Math.cos(t / 1.6));
    return hull + quirk + (t &gt;= 11 ? sc_effect : 0) + 0.12 * scBase.tNoise[t - 1];
  });
